assignments.value:
={{
  $('Prepare Memory - Existing').isExecuted
    ? (
        $('Prepare Memory - Existing').item.json.Datos_Clave
        + '\n\n'
        + 'Intención: ' + $('AI Agent').item.json.output.intencion
        + '\nÚltima solicitud: ' + $('When chat message received').item.json.chatInput
      )
    : (
        'Intención: ' + $('AI Agent').item.json.output.intencion
        + '\nÚltima solicitud: ' + $('When chat message received').item.json.chatInput
      )
}}

={{
  $('Prepare Memory - Existing').isExecuted
    ? Number($('Prepare Memory - Existing').item.json.num_intercambios) + 1
    : Number($('Prepare Memory - New').item.json.fields?.num_intercambios ?? 0) + 1
}}

